/*
 * Linker version script: export symbols with the GLIBC_PRIVATE version tag.
 *
 * Kindle's system libresolv.so.2 (glibc 2.20) expects h_errno@GLIBC_PRIVATE
 * and __res_maybe_init@GLIBC_PRIVATE, but our bundled ld-linux (glibc 2.42)
 * no longer provides them.  By exporting these symbols from gst-play itself,
 * we satisfy the dynamic linker at runtime.
 *
 * See gst-play.c for the corresponding __asm__(".symver ...") definitions.
 */
GLIBC_PRIVATE {
    global:
        h_errno;
        __res_maybe_init;
};
